inline void drawFrame(TFT_eSPI& tft, uint16_t frameIdx, int32_t x = 0, int32_t y = 0) {
  if (frameIdx >= ANIM_FRAMES) return;
  const uint8_t* p = anim_frames[frameIdx];
  uint16_t len = anim_frame_lens[frameIdx];
  tft.setAddrWindow(x, y, DISPLAY_WIDTH, DISPLAY_HEIGHT);
  for (uint16_t i = 0; i < len; i += 2) {
    uint8_t count = p[i];
    uint8_t colorIdx = p[i + 1];
    uint16_t color = anim_palette[colorIdx];
    tft.pushBlock(color, count);
  }
}

